export const POKEDEX=ROWS.map(([id,name,num,types,hp,atk,def,spa,spd,spe,abilities,gen,rarity,spriteid])=>Object.freeze({id,name,num,types:Object.freeze(types.split(',')),baseStats:Object.freeze({hp,atk,def,spa,spd,spe}),bst:hp+atk+def+spa+spd+spe,abilities:Object.freeze(abilities.split(',')),gen,rarity,spriteid:spriteid||id}));
// Imagenes servidas por Pokemon Showdown. Son arte de Nintendo/Creatures/GAME FREAK alojado por un
// tercero: no se copia nada al repositorio y si no hay internet la interfaz cae al emblema propio.
export const SPRITE_BASE='https://play.pokemonshowdown.com/sprites';
export const SPRITE_KINDS={front:['ani','gif'],back:['ani-back','gif'],staticFront:['gen5','png'],staticBack:['gen5-back','png']};
export function spriteUrl(spriteid,kind='front'){
 const [folder,ext]=SPRITE_KINDS[kind]||SPRITE_KINDS.front;
 return spriteid?SPRITE_BASE+'/'+folder+'/'+spriteid+'.'+ext:null;
}
const BY_ID=new Map(POKEDEX.map(p=>[p.id,p]));
export const findPokemon=id=>BY_ID.get(id)||null;
export const pokemonByRarity=rarity=>POKEDEX.filter(p=>p.rarity===rarity);
// Catalogo de Random Battle: qué puede aparecer en ese modo. Incluye formas que el jugador no
