/** Multiplicador de un tipo de ataque contra uno o dos tipos defensores. */
export function typeEffectiveness(attackType,defenderTypes){
 if(!attackType||!Array.isArray(defenderTypes)||!defenderTypes.length)return 1;
 let total=1;
 for(const defense of defenderTypes)total*=CHART[attackType]?.[defense]??1;
 return total;
}
