const MOVE_CATEGORIES=['Physical','Special','Status'];
const MOVES=new Map(MOVE_ROWS.map(([id,name,type,category,power])=>[id,Object.freeze({id,name,type,category:MOVE_CATEGORIES[category],basePower:power})]));
export const findMove=id=>MOVES.get(String(id||'').toLowerCase().replace(/[^a-z0-9]/g,''))||null;
export const moveCount=()=>MOVES.size;
// El motor puede sacar formas cosméticas que no están en POKEDEX (Pikachu-Partner, Vivillon-Tundra…).
// Se prueba el nombre exacto y después se le van sacando sufijos hasta dar con la especie base.
const BY_NAME=new Map(POKEDEX.map(p=>[p.name.toLowerCase(),p]));
export function findSpeciesByName(name){
 let text=String(name||'').trim();
 while(text){
  const hit=BY_NAME.get(text.toLowerCase());
  if(hit)return hit;
  const cut=text.lastIndexOf('-');
  if(cut<=0)return null;
  text=text.slice(0,cut);
 }
 return null;
}
